// WD-08-R1: verify the bridge secret FIRST and never throw for a bad/missing secret -- an
// uncaught throw here (with no Respond node reachable on this path) is what made n8n's default
// webhook behavior mask a rejected request as HTTP 200. Return a flag instead so a dedicated IF
// node can route to an explicit 401 response with no detail leakage. Every other validation below
// is unrelated to this ticket and keeps its existing throw-based behavior.
const got = $input.first().json.headers?.['x-gaiada-bridge-secret'];
const secretOk = !!got && got === $env.N8N_BRIDGE_SECRET;
if (!secretOk) return [{ json: { authFailed: true } }];
const e = $input.first().json.body ?? {};
if (e.v !== 1) throw new Error(`unexpected envelope version ${e.v}`);
if (!e.tenantId) throw new Error('tenantId required');
const transcript = (e.transcript && String(e.transcript).trim()) ? String(e.transcript) : '';
if (!transcript) throw new Error('v1 requires body.transcript (audioRef-only transcription is a later enhancement)');
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const key = e.meetingId || '';
const dup = key ? Object.prototype.hasOwnProperty.call(store.seen, key) : false;
if (key && !dup) { store.seen[key] = Date.now(); const ids = Object.keys(store.seen); if (ids.length > 1000) for (const k of ids.slice(0, ids.length - 1000)) delete store.seen[k]; }
return [{ json: { authFailed: false, dup, tenantId: e.tenantId, meetingId: key, title: e.title ?? null, transcript } }];

// E1 fix (superseding an earlier attempt in this same ticket that was ALSO wrong -- see below):
// on a re-posted meetingId (n8n's own in-memory dedupe fired, `store.seen` in the upstream Code
// node) resolve whether a run ALREADY exists via the read-only pipeline.runBySourceMeeting tool,
// which queries pipeline_runs.source_meeting_id directly -- the authoritative link set at run
// creation. Deliberately NOT pipeline.createRun: `store.seen` is written on FIRST SIGHT of the
// webhook post, before createRun ever runs on the main path, so dup===true means only "this
// workflow has seen this meetingId", not "a run exists for it". If the first attempt's main path
// failed AFTER the marker was set but BEFORE createRun ran, a retry landing here with a
// create-capable call would find no source_meeting_id match and take the INSERT path -- minting
// a phantom run with no momRef/stages/clientId and fanning out a scope-signoff gate for nothing.
// A pure read cannot do that: on no match it just answers null. Best-effort only: if this lookup
// itself errors (hub/platform hiccup, or no run created yet), still answer deduped:true with
// runId:null rather than let a read-only lookup failure turn an honest dedupe ack into a
// workflow error.
let runId = null;
try {
  const raw = $input.first().json.data ?? $input.first().json.body ?? '';
  const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
  const rpc = JSON.parse(line.slice(5).trim());
  if (!rpc.result?.isError) {
    const parsed = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}');
    runId = parsed.runId ?? null;
  }
} catch { runId = null; }
return [{ json: { runId } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'meeting.recordingContext error');
let parsed = {}; try { parsed = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch { parsed = {}; }
const v = $('Verify + dedupe + resolve transcript').first().json;
return [{ json: { ...v, clientId: parsed.clientId ?? null, projectId: parsed.projectId ?? null } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'llm.summarize error');
const mom = rpc.result?.content?.[0]?.text ?? '';
const v = $('Parse recording context (F-1)').first().json;
return [{ json: { ...v, mom } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'llm.extract prd error');
let parsed = {}; try { parsed = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch { parsed = {}; }
const prev = $('Parse MOM').first().json;
return [{ json: { ...prev, prd: { content: parsed.content ?? '', confidence: (typeof parsed.confidence === 'number' ? parsed.confidence : null) } } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'llm.extract report error');
let parsed = {}; try { parsed = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch { parsed = {}; }
const prev = $('Parse prd').first().json;
return [{ json: { ...prev, report: { content: parsed.content ?? '', confidence: (typeof parsed.confidence === 'number' ? parsed.confidence : null) } } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'llm.extract scope error');
let parsed = {}; try { parsed = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}'); } catch { parsed = {}; }
const prev = $('Parse report').first().json;
const scope = { content: parsed.content ?? '', confidence: (typeof parsed.confidence === 'number' ? parsed.confidence : null) };
// Assemble the pipeline.createRun arguments; drop null confidence so the tool schema stays happy.
// F-1: clientId comes from the meeting_recordings lookup (Parse recording context), not the
// frozen webhook payload — null when the recording has no client (no regression, portal scoping
// just stays unset exactly as it already did for those runs).
const stage = (track, name, art) => { const s = { track, name, status: 'done', artifactRef: art.content }; if (typeof art.confidence === 'number') s.confidence = art.confidence; return s; };
const args = { tenantId: prev.tenantId, sourceMeetingId: prev.meetingId || undefined, title: prev.title || undefined, momRef: prev.mom || undefined, clientId: prev.clientId || undefined, stages: [ stage('delivery', 'prd_extract', prev.prd), stage('report', 'report_extract', prev.report), stage('scope', 'scope_extract', scope) ] };
return [{ json: { args, prdConfidence: prev.prd.confidence } }];

const raw = $input.first().json.data ?? $input.first().json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
const rpc = JSON.parse(line.slice(5).trim());
if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? 'pipeline.createRun failed (a medium+ write would suspend here)');
const run = JSON.parse(rpc.result?.content?.[0]?.text ?? '{}');
return [{ json: { runId: run.id, deduped: run.deduped ?? false, prdConfidence: $('Assemble createRun args').first().json.prdConfidence } }];
